package UAVAirframe {
  attribute def Real;

  port def StructuralMount {
    attribute loadLimitN : Real;
  }

  part def WingAssembly {
    attribute wingspanM : Real = 3.2;
    attribute wingAreaM2 : Real = 0.96;
    attribute massKg : Real = 2.4;
    port rootMount : StructuralMount;
  }

  part def Fuselage {
    attribute lengthM : Real = 1.85;
    attribute massKg : Real = 3.1;
    port wingAttach : StructuralMount;
    port tailAttach : StructuralMount;
  }

  part def Tailplane {
    attribute massKg : Real = 0.85;
    port boomMount : StructuralMount;
  }

  part def FixedWingUAV {
    attribute maxTakeoffMassKg : Real = 12.0;
    part fuselage : Fuselage;
    part wing : WingAssembly;
    part tail : Tailplane;
    connection wingJoint connect fuselage.wingAttach to wing.rootMount;
    connection tailJoint connect fuselage.tailAttach to tail.boomMount;
  }
}

package CoreQuantities {
  abstract attribute def ScalarValue;
  attribute def Real :> ScalarValue;
  attribute def Length :> Real;
  attribute def Mass :> Real;
  attribute def Time :> Real;
  attribute def Temperature :> Real;
  attribute def Velocity :> Real;
  attribute def Force :> Real;
  attribute def Power :> Real;
  attribute def Voltage :> Real;
  attribute def Current :> Real;

  part def PhysicalElement {
    attribute mass : Mass;
    attribute ambientTemp : Temperature;
  }

  part def ElectromechanicalDevice :> PhysicalElement {
    attribute ratedVoltage : Voltage;
    attribute ratedCurrent : Current;
    attribute ratedPower : Power;
  }
}

package AutonomousBraking {
  attribute def Real;

  port def RadarTrackPort {
    attribute timeToCollisionS : Real;
    attribute relativeSpeedMps : Real;
  }

  port def HydraulicCommandPort {
    attribute targetDecelMps2 : Real;
    attribute linePressureBar : Real;
  }

  action def SenseObstacle {
    attribute rangeM : Real;
    attribute ttcS : Real;
  }

  action def ComputeDeceleration {
    attribute decelCmdMps2 : Real;
  }

  state def AebControllerStates {
    state Standby;
    state Warning;
    state PartialBraking;
    state FullEmergencyBraking;
  }

  part def RadarSensor {
    port trackOut : RadarTrackPort;
  }

  part def BrakeActuator {
    attribute maxPressureBar : Real = 180.0;
    port cmdIn : HydraulicCommandPort;
  }

  part def AebController {
    attribute warningTtcS : Real = 2.4;
    attribute emergencyTtcS : Real = 1.1;
    port trackIn : RadarTrackPort;
    port brakeOut : HydraulicCommandPort;
  }

  part def AebSystem {
    part radar : RadarSensor;
    part ecu : AebController;
    part actuator : BrakeActuator;
    connection sensorLink connect radar.trackOut to ecu.trackIn;
    connection brakeLink connect ecu.brakeOut to actuator.cmdIn;
  }
}

